svg.script:
const svg = document.documentElement;
const bias = document.getElementById("bias");
const step = document.getElementById("step");
const count = document.getElementById("count");
const play = document.getElementById("play");
const maxStep = Number(step.max);
const peak = 2.2, sigma = 0.62, variance = sigma ** 2;
const grid = Array.from({length: 121}, (_, i) => (i - 60) / 10);
const weights = grid.map(z => Math.exp(-z * z / 2));
const totalWeight = weights.reduce((sum, w) => sum + w, 0);

// Along the line joining the peaks, forward KL pulls toward E_P[u] = 0.
// Reverse KL pulls toward the component centers weighted by their posterior under Q.
// The perpendicular marginal is identical, so it drops out of both gradients.
function fit(reverse) {
  let mean = 1.5;
  const means = [mean];
  for (let t = 0; t < maxStep; t++) {
    let targetMean = 0;
    if (reverse) {
      for (let i = 0; i < grid.length; i++) {
        const u = mean + sigma * grid[i];
        targetMean += weights[i] / totalWeight * peak * Math.tanh(peak * u / variance);
      }
    }
    mean += 0.2 * (targetMean - mean);
    means.push(mean);
  }
  return means;
}

// Integrate Q over the shaded strip |u| < 0.8 (midpoint rule).
function valleyMass(mean) {
  const dx = 1.6 / 64;
  let sum = 0;
  for (let i = 0; i < 64; i++) {
    const z = (-0.8 + (i + 0.5) * dx - mean) / sigma;
    sum += Math.exp(-z * z / 2);
  }
  return dx * sum / (sigma * Math.sqrt(2 * Math.PI));
}

const panels = ["m", "i"].map(id => {
  const panel = document.getElementById(id + "-panel");
  return { means: fit(id === "i"), shape: panel.querySelector(".fit"), value: panel.querySelector(".value") };
});
const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
let progress = maxStep, frame = 0;
function draw(time) {
  progress = time;
  const t = Math.floor(time), next = Math.min(t + 1, maxStep);
  const blend = reducedMotion.matches ? 0 : time - t;
  for (const {means, shape, value} of panels) {
    const mean = Number(bias.value) * (means[t] + blend * (means[next] - means[t]));
    shape.setAttribute("x", mean);
    value.textContent = (100 * valleyMass(mean)).toFixed(1) + "%";
  }
  step.value = t;
  count.value = t + " / " + maxStep;
  play.textContent = frame ? "暂停" : time === maxStep ? "重播" : "播放";
}
function stop() {
  cancelAnimationFrame(frame);
  frame = 0;
}
step.addEventListener("input", () => { stop(); draw(Number(step.value)); });
bias.addEventListener("change", () => { stop(); draw(progress); });
play.addEventListener("click", () => {
  if (frame) { stop(); draw(progress); return; }
  const start = progress === maxStep ? 0 : progress;
  const startedAt = performance.now();
  function tick(now) {
    const time = Math.min(maxStep, start + Math.max(0, now - startedAt) / 220);
    frame = time < maxStep ? requestAnimationFrame(tick) : 0;
    draw(time);
  }
  frame = requestAnimationFrame(tick);
  draw(start);
});

const narrow = matchMedia("(max-width: 530px)");
function layout() {
  const small = narrow.matches;
  svg.setAttribute("viewBox", small ? "0 0 344 668" : "0 0 696 378");
  document.getElementById("m-panel").setAttribute("transform", small ? "translate(6 67)" : "translate(12 70)");
  document.getElementById("i-panel").setAttribute("transform", small ? "translate(6 326)" : "translate(354 70)");
  const toolbar = document.getElementById("toolbar");
  toolbar.setAttribute("width", small ? 308 : 660);
  toolbar.setAttribute("height", small ? 78 : 39);
  toolbar.setAttribute("y", small ? 586 : 335);
  if (window.frameElement?.tagName === "OBJECT") {
    window.frameElement.style.aspectRatio = small ? "344 / 668" : "696 / 378";
  }
}
narrow.addEventListener("change", layout);
layout();
document.querySelector(".controls").hidden = false;
draw(progress);
